#ifndef MCP_SERVER_H
#define MCP_SERVER_H

#include <esp_http_server.h>

/**
 * @brief MCP server (Model Context Protocol, streamable HTTP, JSON-RPC over POST /mcp)
 *
 * Optional: off by default, switched on in the WebUI (Setup). Every request needs the access token as bearer token. The token is
 * generated by the device, shown once and stored as SHA-256 hash in NVS (survives reboot and power loss).
 * The tools call the REST endpoints of this device (loopback), so every action behaves like the WebUI.
 */

/// Loads the state (enabled, system actions, token hash) from NVS. Call once after nvs_flash_init()
void mcpInit();

/// Registers POST /mcp (token) and GET/POST /api/mcp (state and token management, HTTP basic auth if configured)
void registerMcpUri(httpd_handle_t server);

#endif // MCP_SERVER_H
